SELECT d.d_year AS year, w.web_state AS state, SUM(i.inv_quantity_on_hand) AS total_quantity, COUNT(*) AS record_count FROM inventory i JOIN date_dim d ON i.inv_date_sk = d.d_date_sk JOIN web_site w ON w.web_open_date_sk = d.d_date_sk WHERE d.d_year = 1923 AND w.web_state = 'OH' GROUP BY d.d_year, w.web_state ORDER BY d.d_year, w.web_state
